import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { VasipuIyakamPage } from './vasipu-iyakam.page';

const routes: Routes = [
  {
    path: '',
    component: VasipuIyakamPage
  },
  {
    path: 'vi-profile',
    loadChildren: () => import('./vasipuiyakamprofile/vasipuiyakamprofile.module').then( m => m.VasipuiyakamprofilePageModule)
  },
  {
    path: 'vi-library',
    loadChildren: () => import('./vasipuiyakamlibrary/vasipuiyakamlibrary.module').then( m => m.VasipuiyakamlibraryPageModule)
  },
  {
    path: 'vi-otp',
    loadChildren: () => import('./vasipuotp/vasipuotp.module').then( m => m.VasipuotpPageModule)
  },
  {
    path: 'vi-session',
    loadChildren: () => import('./vasipuiyakamsession/vasipuiyakamsession.module').then( m => m.VasipuiyakamsessionPageModule)
  },
  {
    path: 'vi-classlist',
    loadChildren: () => import('./vasipuclasslist/vasipuclasslist.module').then( m => m.VasipuclasslistPageModule)
  },
  {
    path: 'vi-photoupload',
    loadChildren: () => import('./photoupload/photoupload.module').then( m => m.PhotouploadPageModule)
  },
  {
    path: 'vi-instruction',
    loadChildren: () => import('./instruction/instruction.module').then( m => m.InstructionPageModule)
  },  {
    path: 'vasipuiyakam-report',
    loadChildren: () => import('./vasipuiyakam-report/vasipuiyakam-report.module').then( m => m.VasipuiyakamReportPageModule)
  }

];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class VasipuIyakamPageRoutingModule {}
